import React from 'react';
import { useOutletContext, useNavigate } from 'react-router-dom';
import ProjectNavbar from '../../components/ProjectNavbar';

const Ins_P1 = () => {
  const context = useOutletContext();
  const { data: insuranceData, setter: setInsuranceData } = context?.ins || {};
  const resumeData = Array.isArray(context) ? context[0] : context?.resumeData;
  const navigate = useNavigate();

  if (!resumeData) {
    return (
      <div className="workspace-container">
        <ProjectNavbar basePath="ins" links={["Claims", "Risk", "Policies", "Ledger"]} />
        <div className="summary-box" style={{ textAlign: 'center', padding: '2rem' }}>
          <h4 style={{ color: '#ef4444' }}>⚠️ No Active Data Stream Found</h4>
          <button onClick={() => navigate('/ins')} className="workspace-button" style={{ backgroundColor: '#2563eb', color: 'white', border: 'none', padding: '0.5rem 1rem', borderRadius: '4px', cursor: 'pointer', marginTop: '1rem' }}>Go to Upload Screen</button>
        </div>
      </div>
    );
  }

  return (
    <div className="workspace-container">
      <ProjectNavbar basePath="ins" links={["Claims", "Risk", "Policies", "Ledger"]} />
      <div className="summary-box">
        <h3>Automated Claims Verification</h3>
        <div className="metrics-grid">
          <div className="metric-card">
            <p>VALIDATION RATIO</p>
            <h4>{resumeData.score}% Confirmed</h4>
          </div>
        </div>
      </div>
    </div>
  );
};
export default Ins_P1;
